return ['domain'=>'wpml-import','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'uk','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Багатоцільовий плагін для експорту та імпорту мультимовного контенту.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'Тригер імпорту більше не приймає ключ в URL. Надішліть його в тілі POST.','Method Not Allowed'=>'Метод не дозволено','Unauthorized'=>'Неавторизовано','No items to process'=>'Немає елементів для обробки','No Content'=>'Немає вмісту','Import process completed'=>'Процес імпорту завершено','Success'=>'Успішно','Import process failed'=>'Процес імпорту не вдався','Internal Server Error'=>'Внутрішня помилка сервера','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d елемент не вдалося обробити, тому його було пропущено.' . "\0" . '%1$s: %2$d елементи не вдалося обробити, тому їх було пропущено.' . "\0" . '%1$s: %2$d елементів не вдалося обробити, тому їх було пропущено.','Cleaning Up Post Data'=>'Очищення даних дописів','Removing temporary and import-related post meta data.'=>'Видалення тимчасових та пов’язаних з імпортом метаданих дописів.','Cleaning Up Term Data'=>'Очищення даних термінів','Removing temporary and import-related term meta data.'=>'Видалення тимчасових та пов’язаних з імпортом метаданих термінів.','Connecting Post Image Attachments'=>'Приєднання вкладень зображень дописів','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Оновлення ID вкладень мініатюр та галерей у перекладених дописах, товарах та довільних типах дописів для посилання на їхні перекладені еквіваленти.','Connecting Inline Term Translations'=>'Приєднання вбудованих перекладів термінів','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Сканування дописів з одним терміном таксономії для визначення та поєднання термінів, призначених цим дописам, з їхніми перекладами.','Deleting Obsolete Original Terms'=>'Видалення застарілих оригінальних термінів','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Видалення оригінальних термінів, які більше не потрібні після створення дублікатів для однойменних термінів. Забезпечення того, щоб жодні дописи не були пов’язані з цими оригінальними термінами.','Duplicating Terms with Shared Names Across Languages'=>'Дублювання термінів зі спільними назвами в різних мовах','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Створення дублікатів правильною мовою для термінів, які мають однакову назву в різних мовах, але належать до дописів різними мовами.','Fixing Imported Post Slugs'=>'Виправлення частин посилань імпортованих дописів','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Регенерація частин посилань перекладених дописів для запобігання конфліктам з оригіналами.','Clearing Translations Cache'=>'Очищення кешу перекладів','Invalidating the persistent cache so it can be regenerated.'=>'Анулювання постійного кешу для його подальшої регенерації.','Marking Parent Terms for Connection'=>'Позначення батьківських термінів для приєднання','Collecting parent terms to connect their translations in the next step.'=>'Збір батьківських термінів для приєднання їхніх перекладів на наступному кроці.','Connecting Posts with Correct Term Translations'=>'Поєднання дописів з правильними перекладами термінів','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Забезпечення поєднання дописів з термінами правильною мовою, особливо якщо ви маєте однакові назви термінів у різних мовах.','Sending Posts for Automatic Translation'=>'Надсилання дописів на автоматичний переклад','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Створення завдань автоматичного перекладу для дописів, позначених для автоперекладу в експортованих даних.','Setting Attachments\' Language'=>'Налаштування мови вкладень','Assigning a language to imported attachments.'=>'Призначення мови імпортованим вкладенням.','Updating Final Post Status'=>'Оновлення кінцевого статусу допису','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Встановлення статусу допису на основі поля «_wpml_import_after_process_post_status» з файлу імпорту (якщо вказано).','Identifying Inline Term Languages'=>'Визначення мов вбудованих термінів','Identifying and setting the language of terms created during post imports.'=>'Визначення та встановлення мови термінів, створених під час імпорту дописів.','Setting Posts’ Language'=>'Налаштування мови дописів','Connecting posts to the default language and translations.'=>'Поєднання дописів з мовою за замовчуванням та перекладами.','Setting Terms’ Language'=>'Налаштування мови термінів','Connecting taxonomy terms to the default (original) language and translations.'=>'Поєднання термінів таксономії з мовою за замовчуванням (оригіналом) та перекладами.','Setting Parent Terms\' Language'=>'Налаштування мови батьківських термінів','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Призначення мови батьківським термінам таксономії, які її не мають, на основі мови, призначеної їхнім дочірнім елементам.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Мігруєте свій мультимовний сайт? Не забудьте також встановити %s на новому сайті перед імпортом контенту, щоб ми могли відновити всі переклади.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Мігруєте свій мультимовний магазин? За допомогою %1$s та %2$s ви можете перенести свій перекладений контент на новий сайт, включаючи перехресні продажі, допродажі та атрибути товарів.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Мігруєте свій мультимовний магазин? Не забудьте встановити %1$s та %2$s на новому сайті перед імпортом контенту, щоб ми могли відновити всі переклади.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Бажаєте імпортувати свій мультимовний контент? Не забудьте встановити %s на оригінальному сайті перед експортом його вмісту, щоб ми могли імпортувати всі переклади сюди.','Looking to import your multilingual content? Install %1$s on this site.'=>'Бажаєте імпортувати свій мультимовний контент? Встановіть %1$s на цьому сайті.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Не забудьте також увімкнути %2$s та %3$s у вашому оригінальному магазині перед експортом його вмісту, щоб ми могли імпортувати всі переклади сюди.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Бажаєте імпортувати свій мультимовний контент? Не забудьте увімкнути %1$s та %2$s у вашому оригінальному магазині перед експортом його вмісту, щоб ми могли імпортувати всі переклади сюди.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Переключитися на всі мови','Linking Product Attribute Translations'=>'Поєднання перекладів атрибутів товарів','Connecting product attributes to their translations based on associated product variations.'=>'Приєднання атрибутів товарів до їхніх перекладів на основі пов’язаних варіантів товарів.','Updating Related Products On Translations'=>'Оновлення пов’язаних товарів у перекладах','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Налаштування посилань на допродажі, перехресні продажі та згруповані товари правильною мовою.','Importing Custom Attribute Labels'=>'Імпортування ярликів довільних атрибутів','Importing labels for product-specific (custom) attributes from the exported data.'=>'Імпортування ярликів для специфічних для товару (довільних) атрибутів з експортованих даних.','You are about to export all your products in all languages at once.'=>'Ви збираєтеся експортувати всі свої товари всіма мовами одночасно.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Не забудьте встановити %1$s та %2$s на новому сайті перед імпортом контенту, щоб ми могли відновити всі переклади.','You are about to export your products in %s.'=>'Ви збираєтеся експортувати свої товари мовою %s.','Registering Product Attributes'=>'Реєстрація атрибутів товарів','Identifying and registering attributes created during product imports for translation.'=>'Визначення та реєстрація атрибутів, створених під час імпорту товарів, для перекладу.','Identifying Product Attribute Languages'=>'Визначення мов атрибутів товарів','Identifying and setting the language of attributes created during product imports.'=>'Визначення та встановлення мови атрибутів, створених під час імпорту товарів.','Export and Import'=>'Експорт та імпорт','I’m using the built-in %s export/import tool'=>'Я використовую вбудований інструмент експорту/імпорту %s','I’m using %s plugin'=>'Я використовую плагін %s','(%1$d/%2$d items)'=>'(%1$d/%2$d елементів)','%d skipped'=>'%d пропущено','(no items)'=>'(немає елементів)','Counting items...'=>'Підрахунок елементів...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Спочатку скажіть нам, як ви збираєтеся створити контент, який будете імпортувати:','Continue'=>'Продовжити','I’m using %1$s and %2$s plugins'=>'Я використовую плагіни %1$s та %2$s','I’m using a different method to export from this site'=>'Я використовую інший метод для експорту з цього сайту','I’m exporting the content from this site'=>'Я експортую контент із цього сайту','I’m exporting the content from a different website or system'=>'Я експортую контент з іншого вебсайту або системи','Before importing, add language columns to your content'=>'Перед імпортом додайте колонки мов до свого контенту','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Переконайтеся, що ваш файл імпорту містить наступні колонки (довільні поля) з інформацією про мову:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: значення, однакове для всіх перекладів кожного елемента. На сайтах електронної комерції це часто буде SKU (артикул).','%s: The language code for each item.'=>'%s: код мови для кожного елемента.','And, you can include these two columns if needed:'=>'І, за потреби, ви можете включити ці дві колонки:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: якщо цей елемент є перекладом, встановіть у цій колонці код мови оригіналу. Якщо це не переклад, залиште її порожньою.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: встановіть «draft» (чернетка) або «published» (опубліковано), щоб визначити статус публікації допису після налаштування мов. Зазвичай це значення буде «published».','Here is an example of importing two items, into your site’s languages (%s):'=>'Ось приклад імпорту двох елементів мовами вашого сайту (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Після того як ви додасте колонки мов до свого мультимовного файлу контенту, імпортуйте його на свій сайт за допомогою будь-якого плагіна для імпорту, якому ви надаєте перевагу.','Before importing, your content needs language information'=>'Перед імпортом вашому контенту потрібна інформація про мову','%s will add the necessary language information to your export.'=>'%s додасть необхідну інформацію про мову до вашого експорту.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Імпортуйте свій мультимовний файл контенту на сайт за допомогою будь-якого плагіна для імпорту, якому ви надаєте перевагу.','Use your favorite import plugin'=>'Використовуйте свій улюблений плагін для імпорту','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Після імпорту контенту він все ще не відображатиме правильну інформацію про мову. Тому ми рекомендуємо імпортувати новий контент як чернетки. Якщо ви імпортуєте оновлення, ви можете залишити вже опублікований контент опублікованим.','Return here, to %s, to set languages and connect translations'=>'Поверніться сюди, до %s, щоб налаштувати мови та поєднати переклади','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Коли ви відвідаєте цю сторінку після імпорту контенту з інформацією про мову, ви зможете запустити %s, щоб застосувати мови та поєднати переклади.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Вже імпортували й досі бачите цей екран? %1$sУсунення несправностей %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Як експортувати та імпортувати контент кількома мовами','%s is ready to update your imported content'=>'%s готовий оновити ваш імпортований контент','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Чудова робота. Ми бачимо %1$d термінів та %2$d дописів, які імпортовані та потребують інформації про мову.','Good job. We see %d terms that are imported and need language information.'=>'Чудова робота. Ми бачимо %d термінів, які імпортовані та потребують інформації про мову.','Good job. We see %d posts that are imported and need language information.'=>'Чудова робота. Ми бачимо %d дописів, які імпортовані та потребують інформації про мову.','Run WPML Import'=>'Запустити WPML Import','Multilingual Import Complete'=>'Мультимовний імпорт завершено']];